"""Home search suggestions rendered locally with Nova controls, no remote typing API."""
import base64,hashlib,json
from html import escape

STYLE='''.searchChoices{position:absolute;left:0;right:0;z-index:8;text-align:left;background:#0e0b16;border:1px solid #3b294e;border-radius:16px;padding:5px;margin-top:8px;box-shadow:0 15px 35px #0008}.searchChoices[hidden]{display:none}.searchChoices a{display:flex;gap:15px;align-items:center;color:#e9def6;text-decoration:none;padding:10px 15px;border-radius:10px;min-height:54px}.searchChoices a:hover,.searchChoices a:focus{background:#241532;outline:none}.searchChoices .suggestIcon{width:20px;height:20px;flex:0 0 20px;background-size:80px 80px}.searchChoices .suggestCopy{min-width:0;display:flex;flex-direction:column;gap:3px}.searchChoices .suggestTitle{font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.searchChoices small{font-size:12px;color:#9784ac}.searchChoices .suggestArrow{margin-left:auto;color:#806894;font-size:17px}'''

SCRIPT=r'''(()=>{const input=document.querySelector('input[name="q"]'),box=document.getElementById('homeSuggestions'),data=JSON.parse(document.getElementById('novaSuggestData').dataset.items);if(!input||!box)return;let timer;const hide=()=>{box.hidden=true;input.setAttribute('aria-expanded','false')};const show=()=>{const query=input.value.trim();box.replaceChildren();if(query.length<2){hide();return}const match=query.toLocaleLowerCase(),rows=[],seen=new Set();for(const item of data.sites){if(rows.length>=3)break;if(!(item.url.startsWith('https://')||item.url.startsWith('http://'))||seen.has(item.url))continue;if((item.title+' '+item.url).toLocaleLowerCase().includes(match)){try{rows.push([item.title,new URL(item.url).hostname,item.url,'home']);seen.add(item.url)}catch{}}}for(const previous of data.recent){if(rows.length>=3)break;if(previous!==query&&previous.toLocaleLowerCase().includes(match))rows.push([previous,'Recherche récente',data.prefix+encodeURIComponent(previous),'reload'])}rows.push([query,'Rechercher avec '+data.engine,data.prefix+encodeURIComponent(query),'search'],[query,'Rechercher sur YouTube','https://www.youtube.com/results?search_query='+encodeURIComponent(query),'video']);for(const [title,detail,url,symbol] of rows){const row=document.createElement('a');row.href=url;row.setAttribute('role','option');const icon=document.createElement('span');icon.className='novaControl suggestIcon';icon.style.backgroundPosition=({home:'-60px 0',reload:'-40px 0',search:'-40px -60px',video:'-60px -60px'})[symbol];icon.setAttribute('aria-hidden','true');const copy=document.createElement('span');copy.className='suggestCopy';const label=document.createElement('span');label.className='suggestTitle';label.textContent=title;const subtitle=document.createElement('small');subtitle.textContent=detail;copy.append(label,subtitle);const arrow=document.createElement('span');arrow.className='suggestArrow';arrow.textContent='↗';row.append(icon,copy,arrow);row.addEventListener('keydown',event=>{if(event.key==='Escape'){input.focus();hide()}else if(event.key==='ArrowDown'){event.preventDefault();(row.nextElementSibling||box.firstElementChild)?.focus()}else if(event.key==='ArrowUp'){event.preventDefault();if(row.previousElementSibling)row.previousElementSibling.focus();else input.focus()}});box.append(row)}box.hidden=false;input.setAttribute('aria-expanded','true')};input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(show,70)});input.addEventListener('focus',()=>{if(input.value.trim().length>=2)show()});input.addEventListener('keydown',event=>{if(event.key==='Escape')hide();else if(event.key==='ArrowDown'&&!box.hidden){event.preventDefault();box.firstElementChild?.focus()}});input.form.addEventListener('submit',hide);document.addEventListener('click',event=>{if(event.target!==input&&!box.contains(event.target))hide()});})();'''

def decorate(html,data):
    engine=data.get('preferences',{}).get('search_engine','Google')
    prefix={'Google':'https://www.google.com/search?q=','DuckDuckGo':'https://duckduckgo.com/?q=','Bing':'https://www.bing.com/search?q=','Nova Search':data.get('nova_search_base','https://nova.local/')+'search?q='}.get(engine,'https://www.google.com/search?q=')
    sites=[{'title':str(e.get('title',''))[:90],'url':str(e.get('url',''))[:2000]} for e in (data.get('bookmarks',[])+data.get('history',[])[:100])[:150] if isinstance(e,dict)]
    payload={'engine':engine,'prefix':prefix,'sites':sites,'recent':data.get('recent_searches',[])[:30]}
    content='<div id="homeSuggestions" class="searchChoices" role="listbox" hidden></div><div id="novaSuggestData" hidden data-items="'+escape(json.dumps(payload,ensure_ascii=False),quote=True)+'"></div>'
    digest=base64.b64encode(hashlib.sha256(SCRIPT.encode()).digest()).decode()
    html=html.replace("default-src 'none';","default-src 'none'; script-src 'sha256-"+digest+"';",1)
    html=html.replace('<input name="q"','<input autocomplete="off" aria-controls="homeSuggestions" aria-expanded="false" name="q"')
    return html.replace('</form>','</form>'+content,1).replace('</style>',STYLE+'</style>',1).replace('</html>','<script>'+SCRIPT+'</script></html>')
